    // Start with the basic Best-Fit objective: minimize remaining space.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": if the post_residual is too small to fit any common item
    // but too large to be considered "full", it's a trap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If post_residual perfectly accommodates the next item, 
    // heavily reward this bin selection.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how tightly it fits the next item.
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.8;
        } else {
            // If the next item won't fit, penalize the bin slightly to encourage 
            // saving it for a smaller future item.
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: If this is a new bin candidate, make it expensive unless
    // the existing bins have very poor residual stats (forcing a spread of items).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins already or if the mean_residual
        // suggests our current bins are already very crowded.
        score += 45.0; 
        if open_bins_count > 0 && mean_residual < 20.0 {
            score -= 30.0;
        }
    }

    // 4. Scarcity/Bottlenecking: If this is the last bin that can fit the item, 
    // lower the score to prioritize using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression weighting: As the stream nears the end, prioritize closing bins
    // by favoring lower post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (1..9 range)
    // by using a quadratic penalty for "near-empty" space.
    let stranded_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size is large, favor larger residuals (smaller post_residual is bad)
    // If next_item_size is small, prioritize tight packing (smaller post_residual is good)
    let lookahead_factor = if next_item_size > 0 {
        let diff = (next_item_size as f64 - post) / bin_capacity as f64;
        diff * 20.0
    } else {
        0.0
    };

    // Favor filling existing bins as the stream progresses to minimize total open bins
    let progress_weight = progress * 15.0;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    // If bin is empty (post == bin_capacity - item_size), add penalty for opening new bin
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As stream progresses, opening new bins becomes increasingly expensive
        30.0 + (progress * 50.0) - (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Combine terms:
    // 1. Post residual (base)
    // 2. Stranded penalty (avoid small gaps)
    // 3. Lookahead alignment
    // 4. New bin penalty
    // 5. Progress-based packing efficiency
    let score = post + stranded_penalty + lookahead_factor + new_bin_penalty - progress_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor bins that reach "clean" capacity thresholds (e.g., leaving 0 or 25 remaining)
    // Minimizing post_residual is standard (Best Fit), but we apply a modulation factor.
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.5;

    // 2. Lookahead Coupling: If next_item_size is large, penalize small residuals that prevent its placement.
    // If next_item_size cannot fit in current post_residual, apply a weight proportional to the "wasted" potential.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 1.2;
    }

    // 3. New Bin Thresholding: If we are forced to open a new bin, ensure the cost is balanced against
    // the current density of open bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the existing bins are highly fragmented.
        // If fitting_bins_count > 0, we heavily penalize the "New Bin" option.
        if fitting_bins_count > 0 {
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, the "New Bin" score is the baseline.
            score = 10.0; 
        }
    } else {
        // 4. Mean Residual Pressure: If current bin is significantly better than the global mean, 
        // prioritize it to keep the mean low (tight packing).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become increasingly aggressive 
    // about filling existing bins to avoid leftover stragglers.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

