pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'sliver' (unusable space < 10, as items are >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Heuristic: Prefer tighter fits (Best Fit principle)
    // We reward placements that leave residual space that is likely to fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for preserving space for the lookahead item
            score -= 40.0;
        } else {
            // Penalty if this placement forces a new bin for the next item
            score += 20.0;
        }
    }

    // Harmonic/Modulo logic: Favor bins that leave room for common factors of capacity (100)
    // Multiples of 20, 25, 50 are generally more flexible for future items
    let remainder = post_residual % 20;
    score += (remainder as f64).powf(1.1);

    // If this is a new bin, apply a structural penalty to discourage unnecessary opening
    if bin_residual == bin_capacity {
        // Only open new if the current mean_residual is very low (bins are full)
        // or if we have very few fitting options
        score += 35.0;
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // If it's an existing bin, reward it if it's currently "tighter" than the mean
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Final adjustment for the 'last chance' scenario
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}
